/*
 * Ed25519 verify, against RFC 8032's own vectors.
 *
 * ============================== READ THIS =============================
 * THE HEX BELOW IS COPIED FROM RFC 8032 SECTION 7.1 AND IS A LITERAL ON
 * PURPOSE. It is not derived from this code, it must never be regenerated by
 * running this code, and a failure here is a BREAK rather than a test to
 * update. The same rule testdata/vectors.h states for the wire vectors, and for
 * the same reason: a vector computed from the implementation it pins moves
 * whenever the implementation moves, and then it pins nothing.
 *
 * If one of these fails, the signature primitive disagrees with every other
 * Ed25519 implementation in the world. The bootloader would then accept
 * signatures nobody else considers valid, or -- far worse -- reject the ones
 * the build system produces, which reads as a hardware fault.
 * ======================================================================
 *
 * These run on the HOST, where donna is correct and fast. They say nothing
 * about whether it fits on an ATmega328P; boot/boot_verify.h has that
 * measurement, and it does not.
 *
 * Built with -DED25519_FORCE_32BIT so the code exercised here is the same
 * 32-bit field arithmetic the AVR build compiles, rather than the uint128 path
 * an x86-64 host would otherwise take. Testing a path the device never runs
 * would be testing the wrong program.
 */

#include <string.h>
#include "unity.h"
#include "boot_verify.h"

void setUp(void) {}
void tearDown(void) {}

static uint8_t nib(char c)
{
    if (c >= '0' && c <= '9') { return (uint8_t)(c - '0'); }
    return (uint8_t)((c | 0x20) - 'a' + 10);
}

static void unhex(const char *h, uint8_t *out, size_t n)
{
    for (size_t i = 0u; i < n; i++) {
        out[i] = (uint8_t)((nib(h[i * 2u]) << 4) | nib(h[i * 2u + 1u]));
    }
}

/* RFC 8032, section 7.1, "TEST 2" -- a one-byte message. */
#define RFC8032_T2_PUB "3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c"
#define RFC8032_T2_MSG "72"
#define RFC8032_T2_SIG "92a009a9f0d4cab8720e820b5f642540a2b27b5416503f8fb3762223ebdb69da" \
                       "085ac1e43e15996e458f3613d0f11d8c387b2eaeb4302aeeb00d291612bb0c00"

/* RFC 8032, section 7.1, "TEST 3" -- a two-byte message. */
#define RFC8032_T3_PUB "fc51cd8e6218a1a38da47ed00230f0580816ed13ba3303ac5deb911548908025"
#define RFC8032_T3_MSG "af82"
#define RFC8032_T3_SIG "6291d657deec24024827e69c3abe01a30ce548a284743a445e3680d7db5ac3ac" \
                       "18ff9b538d16f290ae67f760984dc6594a7c15e9716ed28dc027beceea1ec40a"

/* RFC 8032, section 7.1, "TEST 1" -- the EMPTY message, which is the case an
 * implementation that special-cases short inputs gets wrong. */
#define RFC8032_T1_PUB "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a"
#define RFC8032_T1_SIG "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555f" \
                       "b8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b"

static void test_rfc8032_test2_verifies(void)
{
    uint8_t pub[32], sig[64], msg[1];

    unhex(RFC8032_T2_PUB, pub, 32u);
    unhex(RFC8032_T2_SIG, sig, 64u);
    unhex(RFC8032_T2_MSG, msg, 1u);
    TEST_ASSERT_EQUAL_INT(TFW_OK, tfw_boot_verify(msg, 1u, sig, pub));
}

static void test_rfc8032_test3_verifies(void)
{
    uint8_t pub[32], sig[64], msg[2];

    unhex(RFC8032_T3_PUB, pub, 32u);
    unhex(RFC8032_T3_SIG, sig, 64u);
    unhex(RFC8032_T3_MSG, msg, 2u);
    TEST_ASSERT_EQUAL_INT(TFW_OK, tfw_boot_verify(msg, 2u, sig, pub));
}

static void test_rfc8032_test1_the_empty_message_verifies(void)
{
    uint8_t pub[32], sig[64];

    unhex(RFC8032_T1_PUB, pub, 32u);
    unhex(RFC8032_T1_SIG, sig, 64u);
    TEST_ASSERT_EQUAL_INT(TFW_OK, tfw_boot_verify(0, 0u, sig, pub));
}

/* THE TAMPERED VECTOR. The same RFC 8032 TEST 2, with one bit of the message
 * flipped. Everything else is byte-for-byte the published value, so a pass here
 * means the primitive accepts a message it was not given -- the failure the
 * whole bootloader exists to prevent. */
static void test_a_tampered_message_is_refused(void)
{
    uint8_t pub[32], sig[64], msg[1];

    unhex(RFC8032_T2_PUB, pub, 32u);
    unhex(RFC8032_T2_SIG, sig, 64u);
    unhex(RFC8032_T2_MSG, msg, 1u);
    msg[0] ^= 0x01u;
    TEST_ASSERT_EQUAL_INT(TFW_ERR_CRYPTO, tfw_boot_verify(msg, 1u, sig, pub));
}

static void test_a_tampered_signature_is_refused(void)
{
    uint8_t pub[32], sig[64], msg[1];

    unhex(RFC8032_T2_PUB, pub, 32u);
    unhex(RFC8032_T2_MSG, msg, 1u);

    for (uint8_t bit = 0u; bit < 8u; bit++) {
        unhex(RFC8032_T2_SIG, sig, 64u);
        sig[bit * 8u] ^= 0x01u;
        TEST_ASSERT_EQUAL_INT(TFW_ERR_CRYPTO, tfw_boot_verify(msg, 1u, sig, pub));
    }
}

/* A signature valid under one key must not verify under another. */
static void test_the_wrong_public_key_is_refused(void)
{
    uint8_t pub[32], sig[64], msg[1];

    unhex(RFC8032_T3_PUB, pub, 32u);     /* TEST 3's key ... */
    unhex(RFC8032_T2_SIG, sig, 64u);     /* ... against TEST 2's signature */
    unhex(RFC8032_T2_MSG, msg, 1u);
    TEST_ASSERT_EQUAL_INT(TFW_ERR_CRYPTO, tfw_boot_verify(msg, 1u, sig, pub));
}

static void test_an_all_zero_signature_is_refused(void)
{
    uint8_t pub[32], sig[64], msg[1];

    unhex(RFC8032_T2_PUB, pub, 32u);
    unhex(RFC8032_T2_MSG, msg, 1u);
    memset(sig, 0, sizeof sig);
    TEST_ASSERT_EQUAL_INT(TFW_ERR_CRYPTO, tfw_boot_verify(msg, 1u, sig, pub));
}

/*
 * The public key slot in a bootloader nobody has provisioned reads as erased
 * flash. It must report that rather than verifying against a constant every
 * build of this source shares -- which would be a root of trust the whole world
 * holds the other half of.
 */
static void test_an_unprovisioned_pubkey_slot_refuses(void)
{
    uint8_t pub[32];
    memset(pub, 0xAA, sizeof pub);

    TEST_ASSERT_EQUAL_INT(TFW_ERR_NOT_PROVISIONED, tfw_boot_pubkey(pub));
    for (uint8_t i = 0u; i < 32u; i++) {
        TEST_ASSERT_EQUAL_UINT8(0u, pub[i]);   /* and it is not left as 0xFF */
    }
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_rfc8032_test2_verifies);
    RUN_TEST(test_rfc8032_test3_verifies);
    RUN_TEST(test_rfc8032_test1_the_empty_message_verifies);
    RUN_TEST(test_a_tampered_message_is_refused);
    RUN_TEST(test_a_tampered_signature_is_refused);
    RUN_TEST(test_the_wrong_public_key_is_refused);
    RUN_TEST(test_an_all_zero_signature_is_refused);
    RUN_TEST(test_an_unprovisioned_pubkey_slot_refuses);
    return UNITY_END();
}
